import json,sys,glob,os,re,collections
W=sys.argv[1]
kinds=collections.Counter(); samples={}
rem=collections.Counter(); remsamples={}
for f in sorted(glob.glob(W+'/agent-*.jsonl')):
    lab=json.load(open(f[:-6]+'.meta.json')).get('description','')
    for line in open(f,errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        if r.get('type')=='attachment':
            a=r.get('attachment') or {}
            k=a.get('type') if isinstance(a,dict) else str(type(a))
            kinds[k]+=1
            s=json.dumps(a,ensure_ascii=False)
            if k not in samples or len(s)>len(samples[k][1]): samples[k]=(lab,s)
        # system-reminder texts inside tool results or user content
        s=line
        for m in re.finditer(r'<system-reminder>(.*?)</system-reminder>', s, re.S):
            t=m.group(1)[:80]
            key=re.sub(r'\d+','N',t)[:60]
            rem[key]+=1
            remsamples.setdefault(key,(lab,m.group(1)[:400]))
print(kinds)
for k,(lab,s) in samples.items(): print('--',k,lab,len(s),s[:700])
print()
for k,n in rem.most_common(40): print(n, '|', remsamples[k][0], '|', remsamples[k][1][:300].replace('\\n',' / '))
EOF
